-- Human-recorded detention evidence and internal claim tracking. No legal/payment eligibility is inferred.
begin;
alter table public.load_detention_evidence add column free_time_minutes integer not null default 120 check(free_time_minutes between 0 and 1440),add column claim_status text not null default 'evidence_only' check(claim_status in('evidence_only','draft','recorded_submitted','recorded_approved','recorded_denied','recorded_paid')),add column requested_amount_cents bigint check(requested_amount_cents is null or requested_amount_cents>=0),add column approved_amount_cents bigint check(approved_amount_cents is null or approved_amount_cents>=0),add column request_id text;
create unique index detention_one_record_per_stop on public.load_detention_evidence(company_id,load_id,stop_id);create unique index detention_request_idempotency on public.load_detention_evidence(company_id,request_id)where request_id is not null;
revoke insert,update on table public.load_detention_evidence from authenticated;grant select on table public.load_detention_evidence to authenticated;
create or replace function public.get_verified_detention_workspace(p_load_id uuid)returns table(stop_id uuid,stop_sequence integer,stop_type text,facility_name text,appointment_at timestamptz,arrival_at timestamptz,departure_at timestamptz,free_time_minutes integer,wait_minutes integer,potential_detention_minutes integer,claim_status text,requested_amount_cents bigint,approved_amount_cents bigint,factual_note text)
language sql stable security definer set search_path=public as $$select s.id,s.stop_sequence,s.stop_type,s.facility_name,coalesce(e.appointment_at,s.appointment_at),e.arrival_at,e.departure_at,coalesce(e.free_time_minutes,120),case when e.arrival_at is not null and e.departure_at is not null then greatest(0,floor(extract(epoch from(e.departure_at-e.arrival_at))/60)::integer)end,case when e.arrival_at is not null and e.departure_at is not null then greatest(0,floor(extract(epoch from(e.departure_at-e.arrival_at))/60)::integer-coalesce(e.free_time_minutes,120))end,coalesce(e.claim_status,'evidence_only'),e.requested_amount_cents,e.approved_amount_cents,e.factual_note from public.load_stops s left join public.load_detention_evidence e on e.company_id=s.company_id and e.load_id=s.load_id and e.stop_id=s.id where s.company_id=public.document_intake_company_id()and s.load_id=p_load_id and public.can_read_load(p_load_id)order by s.stop_sequence$$;
create or replace function public.save_verified_detention_record(p_load_id uuid,p_stop_id uuid,p_arrival_at timestamptz,p_departure_at timestamptz,p_free_time_minutes integer,p_claim_status text,p_requested_amount_cents bigint,p_approved_amount_cents bigint,p_note text,p_request_id text)returns uuid language plpgsql security definer set search_path=public as $$declare v_company uuid:=public.document_intake_company_id();v_user uuid:=auth.uid();v_role text:=public.current_business_role();v_id uuid;v_appointment timestamptz;begin if v_company is null or v_user is null or v_role not in('super_admin','owner','dispatcher','accounting')then raise exception 'Not authorized to record detention evidence';end if;if p_request_id is null or char_length(p_request_id)not between 8 and 200 or p_note is null or char_length(trim(p_note))not between 3 and 2000 then raise exception 'Factual note required';end if;select id into v_id from public.load_detention_evidence where company_id=v_company and request_id=p_request_id;if v_id is not null then return v_id;end if;select s.appointment_at into v_appointment from public.load_stops s where s.company_id=v_company and s.load_id=p_load_id and s.id=p_stop_id;if not found then raise exception 'Same-company load stop not found';end if;if p_arrival_at is null or p_departure_at is null or p_departure_at<p_arrival_at or p_free_time_minutes not between 0 and 1440 or p_claim_status not in('evidence_only','draft','recorded_submitted','recorded_approved','recorded_denied','recorded_paid')then raise exception 'Invalid detention facts';end if;if p_requested_amount_cents is not null and p_requested_amount_cents<0 or p_approved_amount_cents is not null and p_approved_amount_cents<0 then raise exception 'Invalid amounts';end if;insert into public.load_detention_evidence(company_id,load_id,stop_id,appointment_at,arrival_at,departure_at,free_time_minutes,claim_status,requested_amount_cents,approved_amount_cents,factual_note,created_by,request_id)values(v_company,p_load_id,p_stop_id,v_appointment,p_arrival_at,p_departure_at,p_free_time_minutes,p_claim_status,p_requested_amount_cents,p_approved_amount_cents,trim(p_note),v_user,p_request_id)on conflict(company_id,load_id,stop_id)do update set appointment_at=excluded.appointment_at,arrival_at=excluded.arrival_at,departure_at=excluded.departure_at,free_time_minutes=excluded.free_time_minutes,claim_status=excluded.claim_status,requested_amount_cents=excluded.requested_amount_cents,approved_amount_cents=excluded.approved_amount_cents,factual_note=excluded.factual_note,request_id=excluded.request_id,updated_at=now()returning id into v_id;return v_id;end$$;
revoke all on function public.get_verified_detention_workspace(uuid),public.save_verified_detention_record(uuid,uuid,timestamptz,timestamptz,integer,text,bigint,bigint,text,text)from public,anon;grant execute on function public.get_verified_detention_workspace(uuid),public.save_verified_detention_record(uuid,uuid,timestamptz,timestamptz,integer,text,bigint,bigint,text,text)to authenticated;
commit;
